css:
.st { font-family: var(--font-heading); font-weight: 700; text-transform: uppercase; margin: 0; color: #f4fbff; }
.st-lead, .st-accent { display: block; }
.st-accent { width: fit-content; max-width: 100%; white-space: pre; background: linear-gradient(120deg, #d705dd, #7a2bd6 42%, #00cdfd 84%, #00fbff); -webkit-background-clip: text; background-clip: text; color: transparent; -webkit-text-fill-color: transparent; }
.st--hero { font-size: clamp(58px, 10vw, 148px); line-height: 0.9; letter-spacing: -0.01em; text-shadow: 0 0 40px rgba(0,205,253,0.15); }
.st--athlete { font-size: min(100px, 15cqw); line-height: 0.88; letter-spacing: 0; white-space: nowrap; }
